d=Deck(8,'降維與資料表示','第 8 週｜壓縮什麼、保留什麼，以及圖形能說明什麼','主教材 Ch.7 pp.221–244','04 s.1–46')
d.add('本週成果與三段安排','0–50 分：維度災難、投影、PCA 幾何。\n\n60–120 分：矩陣推導、保留維度、壓縮與實作。\n\n130–180 分：隨機投影、流形方法與結果解讀。\n\n成果：能做 PCA、解釋變異比例，並辨識視覺化的限制。',weight=1)
d.fig('7-1','維度增加：大部分空間可能靠近邊界','高維空間的距離與密度直覺，不能直接沿用二維經驗。')
d.add('維度災難帶來三個問題','- 要維持相似的資料密度，所需樣本可能大幅增加。\n- 距離變得較不具區辨力，近鄰與分群更難。\n- 特徵過多增加計算、雜訊與過擬合風險。\n\n降維可能幫助，但也可能丟掉預測所需訊息。','主教材 Ch.7 pp.222–223')
d.fig('7-2','投影：資料是否接近某個低維子空間？','把三維點投影到平面；若偏離平面的變化很小，損失可能有限。')
d.fig('7-3','在投影平面建立新的座標','主成分通常是原始特徵的線性組合，不等同刪掉幾個原始欄位。')
d.fig('7-4','Swiss roll：彎曲流形無法靠平面直接攤開','資料內在可能接近二維，但嵌在三維且彎曲；線性投影會重疊。')
d.fig('7-5','攤開流形：保留局部鄰近關係','流形學習假設資料集中在低維結構附近；真實資料未必符合。')
d.fig('7-6','降維之後，分類邊界不一定更簡單','某些目標在流形座標容易分，其他目標卻可能更難；要看任務。')
d.fig('7-7','PCA：選擇投影後變異最大的方向','第一主成分保留最多變異；後續方向與前面正交，再保留剩餘變異。')
d.add('PCA 的兩個等價觀點','1. 在正交線性投影中，最大化保留的變異。\n2. 在固定維度下，最小化平方重建誤差。\n\n先中心化資料；標準化是否適合，要依單位與任務判斷。\n\n變異大不代表對標籤更有預測力。','主教材 Ch.7 pp.227–228；舊稿 04 s.4–8',note='PCA 類別會中心化但不自動把所有特徵縮成單位變異。')
d.activity('先猜方向，再計算','資料點為 $(-2,-2),(-1,-1),(1,1),(2,2)$。\n\n1. 哪條線能完整保留資料？\n2. 投影到 x 軸與投影到對角線，哪個重建誤差小？\n3. 若只留下「最大變異」，是否一定保留分類訊息？','主方向為 (1,1)/√2，對角線重建誤差0；x軸投影丟掉 y 變化。若標籤由小變異方向決定，PCA可能丟掉關鍵訊息。',weight=11)
d.br()
d.add('PCA 的 SVD 寫法與矩陣形狀',r'$$X_c=X-\mathbf1\mu^T=U\Sigma V^T$$'+'\n\n'+r'$V$ 的欄為主成分方向。令 $W_d=[v_1,\ldots,v_d]\in\mathbb R^{n\times d}$。'+'\n\n'+r'$$Z=X_cW_d\in\mathbb R^{m\times d}$$','主教材 Ch.7 pp.229–230，式 7-1、7-2',note='NumPy 返回 Vt，sklearn components_ 每列一個主成分；不要把轉置方向混用。')
d.add('從共變異矩陣推導第一主成分',r'$$C=\frac1{m-1}X_c^TX_c,\qquad\max_{\|w\|=1} w^TCw$$'+'\n\n'+r'$$\mathcal L(w,\lambda)=w^TCw-\lambda(w^Tw-1)\Rightarrow Cw=\lambda w$$'+'\n\n選最大特徵值對應的單位特徵向量；後續方向依特徵值排序。','舊稿 04 s.9–14；主教材 Ch.7 pp.228–229（推導補充）',note='限制 ||w||=1 避免把方向任意放大；最大特徵值等於此方向的樣本變異。',cls='small',core=False)
d.add('手算例：同一條線的共變異矩陣',r'前段四點已中心化，$C=\frac{10}{3}\begin{bmatrix}1&1\\1&1\end{bmatrix}$。'+'\n\n'+r'特徵值為 $20/3$ 與 $0$；第一方向為 $(1,1)^T/\sqrt2$。'+'\n\n第一主成分保留 100% 變異；主成分符號反轉不改變子空間。','教學自製數例；舊稿 04 s.13–23',note='XTX 每項10，樣本共變異分母3；若用分母m，特徵值尺度改變但方向與變異比例不變。')
d.add('解釋變異比例與保留維度',r'$$\rho_j=\frac{\lambda_j}{\sum_l\lambda_l},\qquad d=\min\left\{q:\sum_{j=1}^q\rho_j\ge\tau\right\}$$'+'\n\n例如 $\\tau=0.95$ 保留 95% 變異；它不是保證保留 95% 分類正確率。','主教材 Ch.7 pp.230–231；舊稿 04 s.15–24')
d.fig('7-8','用累積曲線選 d：壓縮與保真之間的折衷','教材 MNIST 例子約需 154 個維度保留 95% 變異；數字會隨資料與前處理而變。')
d.add('PCA 程式：先切分，再學投影','```python\nfrom sklearn.decomposition import PCA\npca = PCA(n_components=0.95, svd_solver="full")\nZ_train = pca.fit_transform(X_train)\nZ_test = pca.transform(X_test)\nX_rebuilt = pca.inverse_transform(Z_test)\nprint(pca.n_components_)\nprint(pca.explained_variance_ratio_.sum())\n```','主教材 Ch.7 pp.231–233；舊稿 04 s.15–24',note='這段未標準化；如需縮放應用 Pipeline。若為CV，PCA也須放入Pipeline逐折fit。',cls='small')
d.add('逆投影：重建時要把平均值加回去',r'$$\hat X=ZW_d^T+\mathbf1\mu^T$$'+'\n\n教材式 7-3 的簡寫 $X_{\\rm recovered}=X_{d\\text{-proj}}W_d^T$，對應中心化座標。\n\n丟掉的維度通常無法完整找回；inverse transform 不代表無損。','主教材 Ch.7 p.234，式 7-3（補明中心化）')
d.fig('7-9','圖像壓縮：重建仍像數字，但細節已減少','同時看圖與量化重建 MSE；下游辨識表現也要單獨評估。')
d.table('PCA 的計算選項',['方法','適合情境','代價或條件'],[['完整 SVD PCA','中小型資料、精確分解','需儲存主要矩陣'],['Randomized PCA','只需少量主成分','近似解，設定 random_state'],['Incremental PCA','資料無法一次放入記憶體','分批 partial_fit；批次需夠大'],['memmap','磁碟映射大陣列','降低一次載入需求，仍有 I/O 成本']],'主教材 Ch.7 pp.233–235；舊稿 04 s.25–29')
d.activity('實作：壓縮率與辨識品質是否一起變好？','對已備妥的 digits 資料，比較 2、10、30 個主成分。\n\n記錄：變異比例、重建 MSE、分類 CV 指標、運行時間。\n\n離線：若特徵值是 `[8, 1.5, 0.5]`，保留 90% 至少需要幾維？','離線答案2維，累積95%；1維只有80%。實作需同切分，同一分類器，PCA放CV內。不要只憑二維散點好看就說模型較好。',weight=12)
d.br()
d.add('隨機投影：不用先找到主方向',r'$$Z=XP,\qquad P_{ij}\sim\mathcal N(0,1/d)$$'+'\n\n用隨機矩陣近似保留有限點集間的距離，計算便宜；不以最大化變異為目標。','主教材 Ch.7 pp.235–237')
d.add('Johnson–Lindenstrauss 維度界線',r'$$d\ge\frac{4\log m}{\varepsilon^2/2-\varepsilon^3/3},\quad0<\varepsilon<1$$'+'\n\n以足夠高的目標維度，讓平方距離大致維持在原距離的 $(1\pm\\varepsilon)$ 範圍。\n\n這是保守理論界，不保證比原始維度更小；不是「任何高維都可壓成 2D」。','主教材 Ch.7 p.235；JL 引理補充',note='教材以5000點、epsilon=.1得到約7300維。整數取法依工具；若要求嚴格下界應上取整。',cls='small',core=False)
d.add('稀疏隨機投影：大部分矩陣元素為零',r'令非零機率為 $r$，非零元素取 $\pm1/\sqrt{dr}$，各占 $r/2$。'+'\n\n可減少儲存與乘法成本；教材常用 $r=1/\sqrt n$。\n\n偽反矩陣可做近似重建，但投影已丟失資訊，不能期待還原全部細節。','主教材 Ch.7 pp.236–238',core=False)
d.fig('7-10','LLE：用鄰居重建每個點，再保持重建關係','先找局部鄰域權重，再尋找能維持這些權重的低維座標。')
d.add('LLE 第一步：找到局部重建權重',r'$$\min_W\sum_i\left\|x_i-\sum_jw_{ij}x_j\right\|^2$$'+'\n\n限制：不是鄰居則 $w_{ij}=0$；每列 $\sum_jw_{ij}=1$。\n\n權重描述局部幾何；鄰居數太少或太多都可能破壞結構。','主教材 Ch.7 p.240，式 7-4；舊稿 04 s.32–35',core=False)
d.add('LLE 第二步：保持權重，移動低維座標',r'$$\min_Z\sum_i\left\|z_i-\sum_jw_{ij}z_j\right\|^2$$'+'\n\n需加中心化與尺度限制，例如 $Z^T\mathbf1=0$、$Z^TZ=I$，排除全部點縮成零的退化解。','主教材 Ch.7 p.240，式 7-5；退化解限制補充',note='W 已固定；與第一步不同，此時求的是 Z。尺度限制的常數 convention 可不同。',core=False)
d.fig('7-11','同一資料用不同降維方法，圖形可能很不同','MDS 著重距離；Isomap 著重沿流形的路徑距離；t-SNE 強調局部鄰近。')
d.table('其他方法與解讀界線',['方法','保留／使用的資訊','注意'],[['MDS','點間距離','大樣本成本高'],['Isomap','近鄰圖的最短路徑距離','鄰居圖錯接會失真'],['t-SNE','局部相似度','群間距離與群大小不宜直接解釋'],['LDA','標籤導向可分性','監督式降維，需防標籤洩漏']],'主教材 Ch.7 p.241；舊稿 04 s.30–45')
d.add('補充 t-SNE：相似度不是原始距離的等比例縮圖',r'$$\operatorname{KL}(P\|Q)=\sum_{i\ne j}p_{ij}\log\frac{p_{ij}}{q_{ij}}$$'+'\n\n高維相似度以局部尺度建立；低維使用厚尾分布。Perplexity 調整有效鄰域尺度。\n\n不同隨機種子與設定可能得到不同圖；UMAP 可作課後比較，不以單張圖確認真實群數。','舊稿 04 s.36–46（補充）',note='不在本週強迫安裝 UMAP。若進一步教其演算法，需另讀原始文獻與套件說明。',core=False)
d.add('離堂檢核與作業','1. PCA 是選原始欄位，還是建立新座標？\n2. 為什麼重建時要加回平均值？\n3. t-SNE 上兩群相距兩倍，能否說原始距離也兩倍？\n\n課後：Ch.7 練習 1–9；對同一資料呈現壓縮、視覺化與預測三種評估。',note='答案：線性組合新座標；PCA在中心化資料操作；不能。LDA需用標籤，所以不是無監督方法。',weight=2)
d.finish()

d=Deck(9,'分群與表示應用','第 9 週｜K-means、群數判斷、影像量化與少量標註','主教材 Ch.8 pp.245–264','05 s.1–11')
d.add('本週成果與節奏','0–50 分：分群任務、K-means 目標與更新。\n\n60–120 分：初始化、群數、輪廓係數與失敗案例。\n\n130–180 分：影像分割、半監督學習與標註策略。\n\n成果：能解釋群的意義、提出選 k 的證據與限制。',weight=1)
d.fig('8-1','沒有標籤時，資料自己呈現什麼結構？','分類用已知答案學習；分群先依特徵相似性找結構，群編號不是已知類別。')
d.add('分群可用於哪些任務？','- 探索顧客、文件或行為的相似群體。\n- 影像顏色量化與資料摘要。\n- 建立距離型特徵，供後續分類或迴歸。\n- 挑選代表樣本標註，協助半監督學習。','主教材 Ch.8 pp.245–247；舊稿 05 s.1–4',note='群名需事後依特徵與業務解釋，不要只用群號就推斷人群本質。')
d.fig('8-2','K-means：把點指派給最近的中心','先指定 k；模型交替估計中心位置與樣本所屬群。')
d.fig('8-3','最近中心形成 Voronoi 分區','邊界由等距位置決定；中心的改變會改變整個分區。')
d.add('目標函數：最小化群內平方距離',r'$$I=\sum_{i=1}^m\|x_i-\mu_{c_i}\|^2$$'+'\n\n$c_i$ 是第 i 筆的群編號；$\mu_{c_i}$ 是該群中心。\n\nK-means 的慣性（inertia）越小，表示同一個 k 下群內更緊密。','主教材 Ch.8 p.253，式 8-1；舊稿 05 s.5–8',note='必須同一資料、同一縮放比較。k增加時inertia自然不增，所以不能只選最低inertia。')
d.add('兩步交替：指派與更新',r'$$c_i\leftarrow\arg\min_j\|x_i-\mu_j\|^2$$'+'\n\n'+r'$$\mu_j\leftarrow\frac1{|C_j|}\sum_{i\in C_j}x_i$$'+'\n\n直到指派或中心移動足夠小；空群需由實作重新初始化等策略處理。','主教材 Ch.8 pp.249–250；舊稿 05 s.5–7')
d.fig('8-4','觀察迭代：中心移動，群邊界跟著改變','每步固定另一部分再改善目標；可收斂到局部解，不保證全域最佳。')
d.activity('手算一維 K-means 的兩步','資料 `[0, 1, 4, 5]`，初始中心 `[0, 4]`。\n\n1. 指派各點到最近中心。\n2. 更新兩個平均中心。\n3. 算更新前、後的 inertia，再看是否還會改群。','初始兩群[0,1]、[4,5]，inertia=2；中心更新為.5、4.5，inertia=1；指派不變。',weight=12)
d.add('群編號沒有天然大小與固定語義','同一個合理分群，某次叫群 0，另一次可能叫群 2。\n\n比較兩次分群時，不能直接把群編號當真實標籤計算 accuracy。\n\n有外部標籤時，可用對編號置換不敏感的指標，例如 ARI；外部標籤仍不等於唯一正確分群。','主教材 Ch.8 pp.248–250；評估補充')
d.br()
d.fig('8-5','不同初始化，可能得到不同局部解','重複啟動並比較 inertia；固定 random_state 方便重現。')
d.add('K-means++ 與多次初始化','K-means++ 讓後續初始中心傾向遠離已選中心，降低一開始擠在一起的風險。\n\n`n_init` 控制重跑次數；教學明確寫出數值，避免依賴版本預設。\n\n```python\nfrom sklearn.cluster import KMeans\nKMeans(n_clusters=5, init="k-means++",\n       n_init=10, random_state=42)\n```','主教材 Ch.8 pp.251–252',note='kmeans++只是改善初始化，仍不是全域最優保證。')
d.add('加速方式：避開多餘距離，或改用小批次','- 加速 K-means：以距離界線減少不必要計算。\n- MiniBatchKMeans：每次用小批次更新中心。\n- 分批方法更省記憶體與時間，但 inertia 可能稍差。\n- 也要計入資料讀取、標準化與批次大小的影響。','主教材 Ch.8 pp.252–253',note='距離界線方法可能增加額外記憶體；不要把所有加速方法都說成更省記憶體。')
d.fig('8-6','k 選錯：可能切碎一群，或合併不同群','左圖 k=3 合併了部分結構；右圖 k=8 切出更多小群。先問切法是否符合分析任務。')
d.fig('8-7','肘部法：找 inertia 改善開始遞減的位置','inertia 隨 k 增加而下降；肘部可能不明顯，也可能不只一個，不能只選最小 inertia。')
d.fig('8-8','平均輪廓分數：把群內與群外距離一起比較','此圖最高值在 k=4；它與 inertia 的肘部可能給出不同線索，下一頁拆解計算公式。')
d.add('輪廓係數：群內近，群外遠',r'$$s_i=\frac{b_i-a_i}{\max(a_i,b_i)}$$'+'\n\n$a_i$：與同群其他點的平均距離。\n\n$b_i$：到每個其他群的平均距離中，最小的一個。\n\n越接近 1 通常越清楚；接近 0 在邊界；負值可能指派不佳。','主教材 Ch.8 pp.255–256；舊稿 05 s.9–10',note='b不是到最近單點的距離。單點群慣例給0；計算需至少2群且群數小於樣本數。',cls='small')
d.fig('8-9','輪廓圖：不要只看整體平均','每群的寬度、負值與大小不均也值得檢查；虛線是整體平均參考。')
d.activity('手算輪廓係數，並質疑平均值','某點 $a=2,b=5$；另一點 $a=4,b=3$。\n\n1. 各算輪廓係數。\n2. 若平均很高但少數群很多負值，能直接宣布分群成功嗎？\n3. 若一群只有一個樣本，為何需特別處理？','兩點分別 .6、-.25。應看每群分布與業務意義；單點群的a沒有同群其他點可平均，常設s=0。',weight=9)
d.fig('8-10','K-means 的限制：橢圓、密度與群大小差異','K-means 偏好近似等向、相近尺度的群；複雜形狀不宜硬套最近中心。')
d.add('縮放之前，先定義什麼叫「相似」','收入、年齡、次數的單位不同，歐氏距離可能被大尺度欄位主導。\n\n標準化是一個選擇；若某欄本來就應更重要，可以明確設定權重並驗證。\n\n分群結果是「特徵、距離、演算法、超參數」共同決定的。','主教材 Ch.8 pp.258–259；舊稿 05 s.11')
d.br()
d.fig('8-11','用 K-means 做顏色量化與影像分割','把每個像素的 RGB 當三維點，以群中心顏色取代原色；少量顏色能形成簡化影像。',note='這是依顏色分組，不是理解物件。小物件可能被合併到背景顏色，教材瓢蟲就是例子。')
d.add('影像轉換的陣列形狀','```python\n# image: (height, width, 3)，數值尺度需一致\npixels = image.reshape(-1, 3)\nkm = KMeans(n_clusters=8, n_init=10, random_state=42)\nlabels = km.fit_predict(pixels)\nsegmented = km.cluster_centers_[labels].reshape(image.shape)\n```\n\n群中心代表典型顏色；此流程未利用像素位置與空間連續性。','主教材 Ch.8 pp.259–261',note='高解析影像可先抽樣訓練或MiniBatch；不要把浮點0–1與整數0–255混用。',cls='small')
d.add('把距離轉成新的特徵表示',r'$$\phi(x)=[\|x-\mu_1\|,\ldots,\|x-\mu_k\|]$$'+'\n\n`KMeans.transform(X)` 得到每筆對各中心的距離；可交給後續監督模型。\n\n中心也屬於學到的前處理，必須只從訓練資料建立。','主教材 Ch.8 p.249；表示學習整合',note='距離表示不一定比原始特徵好，應對照無分群轉換的基準。')
d.add('只有 50 個標籤：先標哪些資料？','隨機挑 50 筆，是最直接的基準。\n\n另一個方法：先把未標註訓練集分成 50 群，每群選最靠近中心的樣本交由人標註。\n\n群數不需要等於類別數；一個數字類別可能有多種書寫樣貌。','主教材 Ch.8 pp.261–262')
d.fig('8-12','代表樣本：每群挑一張最接近中心的圖','人類只標這些代表樣本；群中心本身是平均向量，未必是一張真實圖。')
d.table('教材少量標註實驗：每一步改變了什麼？',['策略','教材測試 accuracy','解讀'],[['前 50 筆有標籤','75.8%','少標籤基準'],['50 個代表樣本','83.4%','標註選樣策略'],['傳播給全群','86.9%','增加偽標籤訓練資料'],['只傳播給較近的一半','88.4%','降低遠端錯誤傳播']],'主教材 Ch.8 pp.261–263（教材結果，非本班重跑）',note='完整標籤教材基準約90.9%。數字是特定digits切分的結果，不能當成普遍改善幅度或因果證明。')
d.add('標籤傳播需要「群內標籤一致」的假設','若某群混合不同真實類別，代表樣本的標籤可能傳錯整群。\n\n可只使用靠近中心的樣本，或保留人工複核的不確定區域。\n\n`LabelPropagation`／`LabelSpreading` 使用相似圖；`SelfTrainingClassifier` 則反覆加入高信心偽標籤。','主教材 Ch.8 pp.263–264',note='这些是不同方法，不要把教材的中心標籤傳播當作LabelPropagation API的內部算法。')
d.add('主動學習：讓模型提出下一筆標註需求','1. 使用目前標籤訓練模型。\n2. 從未標註資料找出不確定、分歧或資訊量高的樣本。\n3. 交由人類標註，再重新訓練。\n4. 記錄標註成本與獨立驗證的改善。','主教材 Ch.8 p.264',note='uncertainty sampling可用最大類別機率最低或entropy最高。不要把測試標籤用來挑樣本。',core=False)
d.activity('實作與報告：群數不是一個神奇答案','對小型資料比較 k=2 到 8，畫 inertia 與 silhouette。\n\n挑兩個候選 k，逐群報告大小、中心、代表樣本與可能意義。\n\n離線組：對「收入×購買次數」的顧客群提出縮放與命名方案，列出不能推論的事情。','評分在多種證據與限制：不能只給最佳k；不得直接把群命名成好／壞客戶而無定義。',weight=13)
d.add('離堂檢核與下週預告','1. k 增加時 inertia 下降，為何還不能直接選最大 k？\n2. 輪廓係數的 b 是哪個距離？\n3. 顏色分群為何不等於物件辨識？\n\n下週：DBSCAN 處理不規則形狀；GMM 提供機率密度。課後：Ch.8 練習 1–5。',note='答案：複雜度增加自然改善；最鄰近其他群的平均距離；僅有RGB缺空間與語義。',weight=2)
d.finish()
